module history;
enum Option<T>{None;Some(value:T);}
fn identity<T>(x:T)->T{return x;}
fn choose(x:Option<i64>)->i64{return match x{Option::Some(n) if n>0=>identity(n),_=>0};}
fn main()->unit!{io}{let n:i64=40;let f:fn(i64)->i64=fn(x:i64)->i64{return x+n;};print(f(choose(Option::Some(2))));print("🧠");}
test fn value()->unit{assert(choose(Option::Some(2))==2);}

